export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();
  return rows.map((row) => row.slug);
}
''', '''/**
 * Replaces the workspace's slug with `slug`, exactly as given, and retires
 * the one it replaces. Returns `null` — having written nothing — when `slug`
 * is not available to this workspace (ADR 0005, rule 2):
 *
 *  - another workspace, live or deleted, has it as its current slug, or
 *  - another workspace retired it and its hold has not ended.
 *
 * A slug this workspace retired itself is always available to it; taking it
 * back ends that retirement. The check and the writes share one transaction
 * so two renames cannot both pass the check.
 */
export async function changeOrgSlug(
  orgId: OrgId,
  slug: string,
): Promise<{ organization: Organization; from: string } | null> {
  return getDb().transaction((tx) => {
    const current = tx
      .select()
      .from(organizations)
      .where(eq(organizations.id, orgId))
      .get();
    if (!current) throw new Error(`Organization ${orgId} not found`);

    if (current.slug === slug) {
      return { organization: toOrganization(current), from: current.slug };
    }

    const now = new Date();
    const stamp = toIsoTimestamp(now);

    const holder = tx
      .select({ id: organizations.id })
      .from(organizations)
      .where(and(eq(organizations.slug, slug), ne(organizations.id, orgId)))
      .get();
    if (holder) return null;

    const heldElsewhere = tx
      .select({ orgId: organizationRetiredSlugs.orgId })
      .from(organizationRetiredSlugs)
      .where(
        and(
          eq(organizationRetiredSlugs.slug, slug),
          ne(organizationRetiredSlugs.orgId, orgId),
          gt(organizationRetiredSlugs.retiredAt, holdCutoff(now)),
        ),
      )
      .get();
    if (heldElsewhere) return null;

    // The slug is current again: end this workspace's own retirement of it.
    // Any other row for it is a lapsed hold (checked above) and goes too.
    tx.delete(organizationRetiredSlugs)
      .where(eq(organizationRetiredSlugs.slug, slug))
      .run();

    tx.insert(organizationRetiredSlugs)
      .values({ orgId, slug: current.slug, retiredAt: stamp })
      .onConflictDoUpdate({
        target: [organizationRetiredSlugs.orgId, organizationRetiredSlugs.slug],
        set: { retiredAt: stamp },
      })
      .run();

    const row = tx
      .update(organizations)
      .set({ slug, updatedAt: stamp })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();

    return { organization: toOrganization(row), from: current.slug };
  });
}

/**
 * Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. A slug
 * is taken while any workspace — live or deleted — has it as its current
 * slug, and while a retirement still holds it; a released slug is free.
 */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const db = getDb();

  const current = db
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();

  const held = db
    .select({ slug: organizationRetiredSlugs.slug })
    .from(organizationRetiredSlugs)
    .where(
      and(
        like(organizationRetiredSlugs.slug, `${prefix}%`),
        gt(organizationRetiredSlugs.retiredAt, holdCutoff(new Date())),
      ),
    )
    .all();

  return [...new Set([...current, ...held].map((row) => row.slug))];
}
''')
