const principal = (t: any, role = "member") => ({ userId: t.userIds[role], email: "x@y.z", activeOrgId: null, expiresAt: "2999-01-01T00:00:00.000Z" }) as any;

describe("rename", () => {
  it("renames, retires, announces once", async () => {
    const t = await createTenant("alpha");
    const seen: any[] = [];
    const un = subscribe("organization.slug_changed", (p) => { seen.push(p); });
    const before = (await getOrganizationSummary(t.actors.owner, t.org.id)).organization;
    const out = await renameOrganizationSlug(t.actors.admin, { orgId: t.org.id, slug: "alpha-new" });
    expect(out).toEqual({ ...before, slug: "alpha-new", updatedAt: out.updatedAt });
    expect((await getOrganizationSummary(t.actors.owner, t.org.id)).organization.slug).toBe("alpha-new");
    expect((await listOrganizationsForUser(t.userIds.owner)).map((o) => o.slug)).toEqual(["alpha-new"]);
    expect((await resolveOrgBySlug("alpha"))?.id).toBe(t.org.id);
    expect((await resolveOrgBySlug("alpha"))?.slug).toBe("alpha-new");
    expect((await resolveActorForOrg(principal(t), "alpha"))?.orgId).toBe(t.org.id);
    expect((await resolveActorForOrg(principal(t), "alpha-new"))?.orgId).toBe(t.org.id);
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({ orgId: t.org.id, actorId: t.userIds.admin, from: "alpha", to: "alpha-new" });
    const page = await listActivity(t.actors.owner, activityFilterSchema.parse({ orgId: t.org.id, action: ["organization.slug_changed"] }));
    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({ actorId: t.userIds.admin, subjectKind: "organization", subjectId: t.org.id, metadata: { from: "alpha", to: "alpha-new" } });

    // no-op
    await renameOrganizationSlug(t.actors.admin, { orgId: t.org.id, slug: "alpha-new" });
    expect(seen).toHaveLength(1);
    expect((await getOrganizationSummary(t.actors.owner, t.org.id)).organization).toEqual(out);
    un();
  });

  it("refuses", async () => {
    const a = await createTenant("beta");
    const b = await createTenant("gamma");
    await expect(renameOrganizationSlug(a.actors.member, { orgId: a.org.id, slug: "beta-2" })).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "gamma" })).rejects.toBeInstanceOf(InvalidSlugError);
    await expect(renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "settings" })).rejects.toBeInstanceOf(InvalidSlugError);
    await expect(renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "Beta!" })).rejects.toBeInstanceOf(InvalidSlugError);
    await expect(renameOrganizationSlug(b.actors.owner, { orgId: a.org.id, slug: "zzz" })).rejects.toThrow();
    expect((await orgRepo.findOrgById(a.org.id))).toEqual(a.org);
    // held by another
    await renameOrganizationSlug(b.actors.owner, { orgId: b.org.id, slug: "gamma-two" });
    await expect(renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "gamma" })).rejects.toBeInstanceOf(InvalidSlugError);
    // creation suffixes a held slug
    const c = await createOrganization(a.userIds.owner, { name: "G", slug: "gamma", plan: "free" });
    expect(c.slug).toBe("gamma-2");
    // deleted workspace's current slug stays unavailable
    await deleteOrganization(b.actors.owner, { orgId: b.org.id, confirmSlug: "gamma-two" });
    await expect(renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "gamma-two" })).rejects.toBeInstanceOf(InvalidSlugError);
    expect(await resolveOrgBySlug("gamma")).toBeNull();
    expect(await resolveOrgBySlug("gamma-two")).toBeNull();
    // updateOrganization cannot smuggle a slug
    const u = await updateOrganization(a.actors.owner, { orgId: a.org.id, slug: "smuggled" } as any);
    expect(u.slug).toBe("beta");
  });

  it("hold boundary and chains", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    const t0 = Date.parse("2027-01-01T00:00:00.000Z");
    vi.setSystemTime(t0);
    const a = await createTenant("delta");
    const b = await createTenant("omega");
    await renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "delta-b" }); // delta retired t0
    vi.setSystemTime(t0 + 10 * DAY);
    await renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "delta-c" }); // delta-b retired t0+10
    expect((await resolveOrgBySlug("delta"))?.id).toBe(a.org.id);
    expect((await resolveOrgBySlug("delta-b"))?.id).toBe(a.org.id);
    vi.setSystemTime(t0 + ORG_SLUG_HOLD_DAYS * DAY - 1);
    expect((await resolveOrgBySlug("delta"))?.id).toBe(a.org.id);
    await expect(renameOrganizationSlug(b.actors.owner, { orgId: b.org.id, slug: "delta" })).rejects.toBeInstanceOf(InvalidSlugError);
    vi.setSystemTime(t0 + ORG_SLUG_HOLD_DAYS * DAY);
    expect(await resolveOrgBySlug("delta")).toBeNull();
    expect(await resolveActorForOrg(principal(a), "delta")).toBeNull();
    expect((await resolveOrgBySlug("delta-b"))?.id).toBe(a.org.id);
    // rename back to own retired slug at any time
    const back = await renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "delta-b" });
    expect(back.slug).toBe("delta-b");
    expect((await resolveOrgBySlug("delta-c"))?.id).toBe(a.org.id);
    // b takes released slug
    const taken = await renameOrganizationSlug(b.actors.owner, { orgId: b.org.id, slug: "delta" });
    expect(taken.slug).toBe("delta");
    expect((await resolveOrgBySlug("delta"))?.id).toBe(b.org.id);
    expect((await resolveOrgBySlug("omega"))?.id).toBe(b.org.id);
    await expect(renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "delta" })).rejects.toBeInstanceOf(InvalidSlugError);
    // after delta-b retirement ended, far future: delta-c released, creation takes it un-suffixed
    vi.setSystemTime(t0 + 100 * DAY);
    expect(await resolveOrgBySlug("delta-c")).toBeNull();
    const c = await createOrganization(a.userIds.owner, { name: "C", slug: "delta-c", plan: "free" });
    expect(c.slug).toBe("delta-c");
  });

  it("schema", () => {
    expect(renameOrganizationSlugSchema.safeParse({ orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA", slug: "ok-slug" }).success).toBe(true);
    expect(renameOrganizationSlugSchema.safeParse({ orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA", slug: "admin" }).success).toBe(false);
  });
});
